const zoneById = Object.fromEntries(ZONES.map(zone=>[zone.id,zone]));
const at = (kind,id,zone,dx,dz,label,description,missions,extra={}) => ({kind,id,zone,x:zoneById[zone].x+dx,z:zoneById[zone].z+dz,label,description,missions,...extra});
const choice = (id,label=id) => ({id,label});
const handle = (id,label,op,values,initial,requires) => ({id,label,op,values:values.map(v=>Array.isArray(v)?choice(...v):choice(v)),initial,requires});
const flag = flag=>({flag});
const notFlag = notFlag=>({notFlag});
const fact = fact=>({fact});
const setting = (setting,value)=>({setting,value});
const installed = itemInstalled=>({itemInstalled});
const trigger = (id,label,requires,effects)=>({id,label,requires,effects});
const condition = (id,label,requires)=>({id,label,requires});

